# English of the Orationes ad diversa and of the Orationes ad supplendum numerum ternarium (body only; the conclusion is
# added from the Latin). 'dm' = after the St Dominic Missal (1959), checked against the Latin; otherwise AI translation.
DM = 'dm'
EN = {
 'd1': ['Grant, we beseech You, almighty God, that the intercession of the holy Mother of God, Mary ever Virgin, and of all the heavenly Powers, and of the blessed Patriarchs, Prophets, Apostles, Martyrs, Confessors and Virgins, and of all Your elect, may everywhere gladden us; that while we recall their merits, we may feel their patronage',
        'Be appeased, O Lord, by the gifts we offer; and at the intercession of the blessed Mother of God, Mary ever Virgin, with all the Saints, defend us from all dangers',
        'Having received, O Lord, the heavenly sacraments, as we recall the memory of blessed Mary ever Virgin and of all Your Saints, grant, we beseech You, that what we do in time we may attain in everlasting joys, helped by their prayers'],
 'd2': [(DM, 'Defend us, we beseech You, O Lord, from all dangers of mind and body; and at the intercession of the blessed and glorious Mary, ever Virgin, Mother of God, with blessed Joseph, Your blessed Apostles Peter and Paul, blessed Dominic our Father, and all the Saints, mercifully grant us safety and peace; that, all adversities and errors being overcome, Your Church may serve You in security and freedom'),
        'Graciously hear us, O God our Saviour, that by the power of this sacrament You may defend us from all enemies of mind and body, giving us grace in this present life and glory in the life to come',
        'May the offering of this divine sacrament cleanse and strengthen us, we beseech You, O Lord; and at the intercession of the blessed Virgin Mary, Mother of God, with blessed Joseph, Your blessed Apostles Peter and Paul, blessed Dominic our Father, and all the Saints, may it make us cleansed from all wickedness and set free from all adversity'],
 'd3': ['Grant, we beseech You, almighty God, that the examples of Your Saints of our Order may stir us to a better life; so that, as we celebrate their memory, we may also imitate their deeds',
        'We offer You, O Lord, the gifts of our devotion; may they be pleasing to You in honour of Your Saints of our Order, and by Your mercy be made salutary for us',
        'Grant us, we beseech You, O Lord, by the intercession of Your Saints of our Order, that what we have touched with our lips we may receive with a pure mind'],
 'd4': ['Grant, we beseech You, almighty God, that the holy Mother of God and all the Saints whose relics are laid up in this church may everywhere help us by their patronage; that, by their present aid, we may rejoice in Your praise in tranquil peace',
        'Receive with a kindly regard, we beseech You, merciful God, the gifts offered to Your majesty, that they may be made salutary for us by the prayers of those whose blessed relics we venerate in this church',
        'Partaking of the divine mysteries, O Lord, we beseech You that, through the merits of the Saints whose venerable relics rest in this church, we may obtain pardon of our sins and be refreshed with the gifts of heavenly grace'],
 'd5': ['Almighty, everlasting God, by whose Spirit the whole body of the Church is sanctified and governed, hear us as we pray for all its orders; that by the gift of Your grace You may be faithfully served by every rank',
        'Grant to Your servants, O Lord, pardon of sins, comfort in life and Your continual guidance; that, serving You, they may come at last to Your mercy',
        'Deliver, we beseech You, O Lord, from sins and enemies Your servants who make supplication to You; that, living in holy conversation, they may be harmed by no adversities'],
 'd6': [(DM, 'O God, the shepherd and ruler of all the faithful, look down in mercy upon Your servant N., whom You have willed to preside over Your Church as her shepherd; grant him, we beseech You, so to profit by word and example those over whom he is set, that together with the flock entrusted to him he may attain to everlasting life'),
        (DM, 'Be appeased, we beseech You, O Lord, by the gifts we offer, and govern with Your continual protection Your servant N., whom You have willed to preside over Your Church as her shepherd'),
        (DM, 'May the reception of this divine sacrament protect us, we beseech You, O Lord, and may it ever save and defend Your servant N., whom You have willed to preside over Your Church as her shepherd, together with the flock committed to him')],
 'd7': [(DM, 'Graciously receive, we beseech You, O Lord, the prayers of Your Church; that, all adversities and errors being destroyed, she may serve You in security and freedom'),
        (DM, 'Protect us, O Lord, who serve Your mysteries; that, cleaving to things divine, we may serve You both in body and in mind'),
        'We beseech You, O Lord our God, that You suffer not to be exposed to human dangers those to whom You grant to rejoice in partaking of divine things'],
 'd8': ['O God, protector of all kingdoms and above all of the Christian Empire, grant to Your servant our Emperor (if he is not yet crowned: Emperor-elect) N. to make wise use of the triumph of Your power; that he who is prince by Your appointment may ever be strong by Your gift',
        'Receive, O Lord, the prayers and offerings of Your Church for the welfare of Your servant who makes supplication to You, and in the protection of the faithful peoples work the ancient wonders of Your arm; that, the enemies of peace being overcome, Christian liberty may serve You in security',
        'O God, who prepared the Roman Empire for the preaching of the Gospel of the eternal King, stretch forth heavenly arms to Your servant our Emperor N.; that the peace of the Churches may be troubled by no storm of war'],
 'd9': ['We beseech You, almighty God, that Your servant N., our King, who by Your mercy has received the government of the realm, may also receive an increase of all virtues; that, fittingly adorned with them, he may shun the monstrous growth of vice, and, being pleasing to You, come at last to You, who are the way, the truth and the life',
        'Sanctify, we beseech You, O Lord, the gifts we offer, that they may become for us the Body and Blood of Your Only-begotten Son, and by Your bounty may in every way profit our King, for obtaining health of soul and body and for fulfilling the office laid upon him',
        'May this saving oblation, O Lord, protect Your servant N., our King, from all adversities; that he may obtain the tranquillity of the Church\'s peace, and after the course of this life come to the everlasting inheritance'],
 'd10': ['Almighty, everlasting God, who alone do great wonders, send down upon Your servants and upon the congregations committed to them the spirit of saving grace; and, that they may please You in truth, pour forth upon them the continual dew of Your blessing',
         'Look favourably, O Lord, on the offerings of Your servants; and grant that the sacrifice which we celebrate for them with devout mind in honour of Your name may profit them unto healing',
         'Accompany with Your continual protection, O Lord, those whom You refresh with the heavenly gift; and grant that those whom You cease not to cherish may be made worthy of everlasting redemption'],
 'd11': [(DM, 'Enlighten, O Lord, the hearts of Your servants with the grace of the Holy Spirit; give them fiery speech, and to those who preach Your word grant an increase of power'),
         (DM, 'Grant Your servants, O Lord, a word of grace; and, hallowing the gifts we offer, visit their hearts, we beseech You, with Your salvation'),
         'Preserve, O Lord, Your servants who have received the Body and Blood of Your Only-begotten Son; and to those who proclaim Your word grant an abundance of graces'],
 'd12': [(DM, 'O God, who kindle us, turned from the vanity of the world, toward the prize of our heavenly calling, pour forth upon us the grace to persevere in You; that, faithfully carrying out our profession, we may ever accomplish what by Your gift we have promised'),
         'Offering to You, O Lord our God, the victim of our devotion, we humbly ask that You would accept us as Your sacrifice through the mortification of carnal life, and form us in the manners that befit our profession',
         (DM, 'O God, who prepare mansions in heaven for those who renounce the world, enlarge our hearts with heavenly gifts; that our life may accord with our name, and our profession be seen in our deeds')],
 'd13': ['Almighty and merciful God, graciously hear the prayers of my lowliness; and make me, Your servant, whom You have granted to serve the heavenly mysteries, with no merits to commend me but by the boundless bounty of Your mercy, a worthy minister of Your holy altars; that what is uttered by my voice may be confirmed by Your sanctification',
         (DM, 'By the power of this sacrament, O Lord, wipe away the stains of my sins; and grant that by Your grace it may make me worthy to carry out the ministry of the office laid upon me'),
         'Almighty, everlasting God, who have willed that I, a sinner, should stand at Your holy altars and praise the might of Your holy name, mercifully grant me through the mystery of this sacrament the pardon of my sins; that I may worthily serve Your majesty'],
 'd14': ['Pour forth, we beseech You, O Lord, upon Your servants the spirit of truth and peace; that they may know with their whole heart what is pleasing to You, and, having known it, follow it with all their strength',
         'May Your clemency, O Lord, look upon the gifts of Your servants, and bestow on them the grace of Your mercy; that they may truly understand what is right in Your eyes, and faithfully carry it out',
         'Grant, we beseech You, merciful God, that the holy things we have received may confirm Your servants in Your will, and make them seek the honour of Your name'],
 'd15': ['O God, who by the grace of the Holy Spirit have poured the gifts of charity into the hearts of Your faithful, grant to Your servants and handmaids, for whom we implore Your mercy, health of mind and body; that they may love You with all their strength, and with all their love do what is pleasing to You',
         'Have mercy, we beseech You, O Lord, on Your servants and handmaids for whom we offer to Your majesty this sacrifice of praise; that by these holy things they may obtain the grace of heavenly blessing and the glory of everlasting happiness',
         'Partaking of the divine mysteries, we beseech You, O Lord, that these saving sacraments may profit unto prosperity and peace those for love of whom we have offered them to Your majesty'],
 'd16': ['Stretch forth, O Lord, to Your faithful the right hand of heavenly help; that they may seek You with their whole heart, and obtain what they rightly ask',
         'Be favourable, O Lord, to our supplications, and graciously accept these offerings of Your faithful, which we offer You for their welfare; and that no one\'s vow may be in vain, no one\'s petition empty, grant, we beseech You, that what we ask in faith we may effectually obtain',
         'Grant to Your faithful, we beseech You, O Lord, constancy in Your faith and sincerity; that, made firm in divine charity, they may be torn from its integrity by no temptations'],
 'd17': ['Incline to us, we beseech You, O Lord, the ears of Your mercy; and grant to our benefactors pardon of sins, perseverance in good works, and in Your kingdom great things for small, and everlasting rewards for temporal',
         'Receive, we beseech You, O Lord, the gift offered to You for Your servants who do good to us; and grant that those whom You have made devoted to You, You may make blessed with You in Your kingdom',
         'By these holy sacraments which we have received, O Lord, look upon Your servants our benefactors; and grant that as their devotion is necessary to us, so it may ever be acceptable to You'],
 'd18': ['Defend, we beseech You, O Lord, by the intercession of blessed Mary ever Virgin, this family from all adversity; and as it lies prostrate before You with its whole heart, mercifully protect it from the snares of its enemies',
         'Receive, we beseech You, almighty God, the offering of our devotion; and by the power of this sacrament protect Your servants from all adversities',
         'Having received the gifts of our redemption, grant, we beseech You, merciful God, that by their celebration we may have the help of Your protection against all adversities'],
 'd19': ['O God, giver of peace and lover of charity, grant Your servants true concord with Your will; that we may be delivered from all the temptations that assail us',
         'Be appeased, O Lord, we beseech You, by these sacrifices; and grant that we who pray to be loosed from our own sins may not be burdened by those of others',
         'Pour forth on us, O Lord, the spirit of Your charity; that those whom You have fed with the one heavenly bread You may in Your goodness make of one heart'],
 'd20': ['Crush, we beseech You, O Lord, the pride of our enemies, and by the power of Your right hand lay low their stubbornness',
         'By the power of this mystery, O Lord, may we be cleansed from our secret sins and delivered from the snares of our enemies',
         'Look upon us, O God our protector, and defend us from the dangers of our enemies; that, all disturbance being removed, we may serve You with free minds'],
 'd21': ['O God, who loosed blessed Peter the Apostle from his chains and made him go forth unharmed, loose the chains of Your servant held in captivity; and through Peter\'s merits grant him to go forth unharmed',
         'May an abundant blessing, we beseech You, O Lord, come down upon these offerings; that it may loose the chains of this captive, and soon gladden us with his deliverance',
         'Mercifully hear our prayers, we beseech You, O Lord; and through these sacraments which we have received loose Your servant from the chains of his captivity'],
 'd22': ['O God, lover and guardian of peace and charity, give to all our enemies peace and true charity, and grant them remission of all their sins; and by Your might deliver us from their snares',
         'Be appeased, we beseech You, O Lord, by the gifts we offer; mercifully deliver us from our enemies, and grant them pardon of their sins',
         'Look upon us, O God our protector, and defend us from the dangers of our enemies; that, all disturbance being removed, we may serve You with free minds'],
 'd23': ['O God, who justify the ungodly and desire not the death of the sinner, we humbly entreat Your majesty that You would graciously protect with heavenly help Your servants who trust in Your mercy, and keep them by Your continual protection; that they may serve You without ceasing and be separated from You by no temptations',
         'By the power of this mystery, we beseech You, O Lord, cleanse us from our own sins, and absolve Your servants from all their offences',
         'May the sacraments which we have received purify us, we beseech You, O Lord; and grant that Your servants may be free from all guilt; that they who are bound by the guilt of conscience may glory in the fullness of the heavenly remedy'],
 'd24': ['Almighty and most gentle God, look graciously upon our prayers, and free our hearts from the temptations of evil thoughts; that we may deserve to become a worthy dwelling of the Holy Spirit',
         'We offer You, O Lord, these oblations for our salvation; that You may cleanse our souls from unclean thoughts and keep them unharmed, and deign to enlighten them with the grace of the Holy Spirit',
         'O God, who enlighten every man that comes into this world, enlighten our hearts, we beseech You, with the splendour of Your grace; that we may worthily serve Your majesty and love You with everlasting charity'],
 'd25': ['Burn our reins and our hearts, O Lord, with the fire of the Holy Spirit; that we may serve You with a chaste body and please You with a clean heart',
         'Break, O Lord, the bonds of our sins; and that we may sacrifice to You a victim of praise with perfect freedom and a clean mind, restore what You gave before, and save by pardon those whom You deigned to save by grace',
         'O Lord, our helper and protector, help us; that our heart and flesh may flourish again in the vigour of purity and the newness of chastity, and, snatched from the hand of hell, may be presented in the joy of the resurrection'],
 'd26': ['O God, who by the patience of Your Only-begotten Son crushed the pride of the ancient enemy, grant us, we beseech You, worthily to recall what He lovingly bore for us, and so by His example to bear our adversities with an even mind',
         'Receive with favour, we beseech You, O Lord, the gifts of our offering, which we present to Your majesty with devout action, that You may deign to bestow on us the gift of patience',
         'May the most holy mysteries which we receive, O Lord, restore to us, we beseech You, the grace we have lost; and, protecting us always and everywhere, bestow on us the gift of patience in all that befalls us'],
 'd27': ['Almighty and most gentle God, who brought forth from the rock a fountain of living water for Your thirsting people, bring forth from the hardness of our hearts tears of compunction; that we may bewail our sins, and by Your mercy obtain their forgiveness',
         'Look graciously, we beseech You, O Lord God, on this offering which we present to Your majesty for our sins, and bring forth from our eyes rivers of tears, by which we may quench the flames we have deserved',
         'Mercifully pour into our hearts, O Lord God, the grace of the Holy Spirit; that it may make us wash away the stains of our sins with sighs and tears, and by Your bounty obtain for us the pardon we desire'],
 'd28': ['O God, who make all things work together for good to those who love You, give to our hearts an inviolable love of Your charity; that the desires conceived by Your inspiration may be changed by no temptation',
         'O God, who renew us after Your image by sacraments and precepts, perfect our steps in Your paths; that through these sacrifices which we offer You may make us truly lay hold of the gift of charity which You have caused us to hope for',
         'May the grace of the Holy Spirit, we beseech You, O Lord, enlighten our hearts, and abundantly refresh them with the sweetness of perfect charity'],
 'd29': ['O God, who resist the proud and give grace to the humble, grant us the virtue of true humility, whose pattern Your Only-begotten Son showed forth in Himself to the faithful; that we may never provoke Your indignation by being lifted up, but rather, being subject, may receive the gifts of Your grace',
         'May this oblation, O Lord God, obtain for us the remission of all our sins and the grace of true humility, and take away from our hearts the concupiscence of the flesh and of the eyes and the ambition of the world; that, living soberly, justly and godly, we may obtain everlasting rewards',
         'May the receiving of this sacrament, O Lord, wipe away the stains of our sins, and by the practice of humility lead us to the heavenly kingdom'],
 'd30': ['Grant us, we beseech You, O Lord, the effect of our devout supplication, and in Your mercy turn away famine; that the hearts of men may know that such scourges come forth when You are angry and cease when You show mercy',
         'O God, who nourish both parts of man\'s nature, renewing it with the food of present gifts and with the sacrament, grant, we beseech You, that the support of both may not be wanting to our bodies or to our souls',
         'Govern with temporal food, we beseech You, O Lord, those whom You deign to instruct with eternal mysteries'],
 'd31': ['From Your house, we beseech You, O Lord, may the spirits of wickedness be driven away, and the malice of storms in the air depart',
         'We offer You, O Lord, praises and gifts, giving thanks for benefits received, and ever humbly entreating You for those yet to be granted',
         'Almighty, everlasting God, who heal us by chastising and preserve us by pardoning, grant to Your suppliants that we may rejoice in the calm of this longed-for consolation, and ever use the gift of Your goodness'],
 'd32': ['O God, who have given men the help even of dumb animals in their labours, we humbly beseech You that the creatures without which human life is not sustained may not perish from our use',
         'Appeased, O Lord, by the sacrifices offered, mercifully bestow Your help in our times',
         'May Your faithful people, O Lord, receive Your blessing, by which they may be saved in body and soul; and in Your clemency, sparing us, bid cease the death of the animals that rages for our demerits'],
 'd33': ['Almighty, everlasting God, who look upon the earth and make it tremble, spare those who fear, be merciful to those who pray; that we who have dreaded Your wrath that shakes the foundations of the earth may ever feel Your clemency that heals its breaches',
         'O God, who founded the earth upon its own firmness, receive the offerings and prayers of Your people; and, wholly removing the dangers of the trembling earth, turn the terrors of Your divine anger into remedies for man\'s salvation; that those who are of the earth and shall return to the earth may rejoice to become citizens of heaven by holy living',
         'Protect us, O Lord, we beseech You, who receive Your holy things; and by Your heavenly gift make firm the earth which we have seen trembling because of our iniquities; that the hearts of men may know that such scourges come forth when You are angry and cease when You show mercy'],
 'd34': ['O God, our refuge and strength, be present to the devout prayers of Your Church, You who are the author of devotion; and grant that what we ask in faith we may effectually obtain',
         'Grant, merciful God, that this saving oblation may ceaselessly free us from our own sins, and make us acceptable to You for obtaining what we ask',
         'To You, O Lord, we cry, humbly beseeching that, as You have said, Ask, and you shall receive, so through the gifts of the sacred mystery which we have received You would deign to grant an abundant hearing to our petitions'],
 'd35': ['Despise not, almighty God, Your people crying out in affliction; but for the glory of Your name be appeased, and help the afflicted',
         'Graciously receive, O Lord, the offerings by which You have willed to be appeased, and by Your mighty goodness to restore us to salvation',
         'Graciously look upon our tribulation, we beseech You, O Lord, and turn away the wrath of Your indignation which we justly deserve'],
 'd36': ['Almighty, everlasting God, in Your goodness forgive the sins of Your servants who confess to You; that guilt of conscience may not harm them unto punishment more than the indulgence of Your mercy may profit them unto pardon',
         'Grant, we beseech You, almighty and merciful God, that this saving oblation may ceaselessly free Your servants from their own sins, and protect them from all adversities',
         'Almighty and merciful God, who would rather that every soul that repents and confesses to You be amended than lost, look upon these Your servants; and by these holy sacraments which we have received turn away from them the wrath of Your indignation, and forgive them all their sins'],
 'd37': ['By Your goodness, we beseech You, O Lord, loose the bonds of our sins; and at the intercession of blessed Mary ever Virgin with all Your Saints, keep us Your servants in all holiness; cleanse from vices all who are joined to us, adorn them with virtues; grant us peace and health, remove our enemies, drive away carnal desires, give good weather, grant the fruits of the earth, bestow charity on our enemies; and to all the faithful, living and dead, grant life and everlasting rest alike',
         'O God, who by the one sacrifice of Your Body loosed the sins of the whole world, be appeased by this offering; wipe away the stains of our crimes, forgive the sins of all Christians living and dead, and grant them everlasting rewards',
         'May the sacraments we have received, we beseech You, O Lord, cleanse away all our crimes, and by the merits of holy Mary, Mother of God, and of all the Saints drive far from us all wickedness and the assaults of the enemy; and may they profit unto pardon all the faithful, living and dead, for whose salvation they were offered to You'],
 'd38': ['Almighty, everlasting God, who have dominion over the living and the dead, and are merciful to all whom You foreknow will be Yours by faith and good works, we humbly beseech You that those for whom we have resolved to pour forth our prayers, whether this present world still holds them in the flesh or the world to come has already received them freed from the body, may, by the intercession of all Your Saints and the clemency of Your goodness, obtain pardon of all their sins',
         'O God, to whom alone is known the number of the elect to be placed in heavenly happiness, grant, we beseech You, that by the intercession of all Your Saints the names of all who have been commended to our prayers, and of all the faithful, may be kept written in the book of blessed predestination',
         'May the sacraments which we have received purify us, we beseech You, O Lord; and by the intercession of all Your Saints grant that this Your sacrament may not be to us guilt unto punishment, but a saving intercession unto pardon; may it be the washing away of sins, the strength of the weak, a defence against all the dangers of the world, and the remission of all sins for the faithful living and dead'],
 'bvmAdv': [(DM, 'O God, who willed that Your Word, at the message of an Angel, should take flesh in the womb of the blessed Virgin Mary, grant to us Your suppliants that we who truly believe her to be the Mother of God may be helped by her intercession with You'),
            'Confirm in our minds, we beseech You, O Lord, the mysteries of the true faith; that we who confess Him who was conceived of the Virgin to be true God and true man may, by the power of His saving resurrection, deserve to come to everlasting joy',
            'Pour forth, we beseech You, O Lord, Your grace into our hearts; that we, to whom the Incarnation of Christ Your Son was made known by the message of an Angel, may by His Passion and Cross be brought to the glory of His Resurrection'],
 'bvmNat': [(DM, 'O God, who by the fruitful virginity of blessed Mary have bestowed on mankind the rewards of eternal salvation, grant, we beseech You, that we may feel her intercession for us, through whom we were found worthy to receive the Author of life'),
            (DM, 'Having received our gifts and prayers, we beseech You, O Lord, at the intercession of blessed Mary, Mother of God, cleanse us by these heavenly mysteries and mercifully hear us'),
            (DM, 'May this communion, O Lord, cleanse us from sin, and at the intercession of the blessed Virgin Mary, Mother of God, make us partakers of the heavenly remedy')],
 'cruce': [(DM, 'O God, who willed that Your Son should undergo for us the gibbet of the Cross, that You might drive from us the power of the enemy, grant to us Your servants that we may obtain the grace of the resurrection'),
           (DM, 'Cleanse us, O merciful God, that the prayers of Your Church, which are pleasing to You, bearing devout gifts, may become more pleasing through the cleansing of our minds'),
           (DM, 'Grant to our minds, almighty God, that through the temporal death of Your Son, which these venerable mysteries attest, we may trust that You have given us everlasting life')],
}
